"use client"

import { useQuery } from "@tanstack/react-query"
import { StatCard } from "../stat-card"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { Info } from "lucide-react"
import { fetchCompanyDetail } from "@/lib/api"

interface CompanyDetailProps {
  company: "construction" | "trading" | "logistics" | "tech"
}

const companyNames = {
  construction: "IREBE Construction Ltd",
  trading: "IREBE Trading Ltd",
  logistics: "IREBE Logistics Ltd",
  tech: "IREBE Tech Solutions Ltd",
}

export function CompanyDetail({ company }: CompanyDetailProps) {
  const { data, isLoading } = useQuery({
    queryKey: ["company-detail", company],
    queryFn: () => fetchCompanyDetail(company),
  })

  if (isLoading) {
    return (
      <div className="text-center py-12 text-muted-foreground">
        Loading company data...
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <Alert className="bg-primary/10 border-primary/20 text-primary">
        <Info className="h-4 w-4" />
        <AlertDescription>
          <strong>{companyNames[company]}</strong> — Last updated: Today at 4:15 PM
        </AlertDescription>
      </Alert>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard
          label="Opening Balance"
          value={data?.openingBalance || "RWF 424,800,000"}
          change="As of start of day"
          changeType="neutral"
          variant="cash"
        />
        <StatCard
          label="Today's Revenue"
          value={data?.revenue || "RWF 42,000,000"}
          change={`${data?.revenueTransactions || 3} transactions`}
          changeType="positive"
          variant="revenue"
        />
        <StatCard
          label="Today's Expenses"
          value={data?.expenses || "RWF 33,800,000"}
          change={`${data?.expenseTransactions || 4} transactions`}
          changeType="neutral"
          variant="expense"
        />
        <StatCard
          label="Closing Balance"
          value={data?.closingBalance || "RWF 450,000,000"}
          change={`Net: +${data?.netChange || "RWF 8,200,000"}`}
          changeType="positive"
          variant="profit"
        />
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="font-serif">{"Today's Transactions"}</CardTitle>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Time</TableHead>
                <TableHead>Description</TableHead>
                <TableHead>Category</TableHead>
                <TableHead>Type</TableHead>
                <TableHead className="text-right">Amount</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {(data?.transactions || []).map((tx, index) => (
                <TableRow key={index}>
                  <TableCell>{tx.time}</TableCell>
                  <TableCell>{tx.description}</TableCell>
                  <TableCell>{tx.category}</TableCell>
                  <TableCell>
                    <Badge
                      variant="outline"
                      className={
                        tx.type === "income"
                          ? "bg-chart-1/10 text-chart-1 border-chart-1/20"
                          : "bg-destructive/10 text-destructive border-destructive/20"
                      }
                    >
                      {tx.type === "income" ? "Income" : "Expense"}
                    </Badge>
                  </TableCell>
                  <TableCell
                    className={`text-right font-serif font-semibold tabular-nums ${
                      tx.type === "income" ? "text-chart-1" : "text-destructive"
                    }`}
                  >
                    {tx.amount}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </div>
  )
}
